// EncounterServiceHandler is an implementation of the healthcare.encounter.v1.EncounterService
// service.
type EncounterServiceHandler interface {
	// SRS-ENC-001, SRS-ENC-002, SRS-ENC-003. An encounter carries its own
	// clinical times; the appointment it answers, where there is one, is a
	// reference rather than a parent.
	OpenEncounter(context.Context, *connect.Request[v1.OpenEncounterRequest]) (*connect.Response[v1.OpenEncounterResponse], error)
	StartEncounter(context.Context, *connect.Request[v1.StartEncounterRequest]) (*connect.Response[v1.StartEncounterResponse], error)
	EndEncounter(context.Context, *connect.Request[v1.EndEncounterRequest]) (*connect.Response[v1.EndEncounterResponse], error)
	// SRS-ENC-006. Invalid state changes are rejected; cancelled and
	// entered-in-error are different facts and stay distinguishable.
	CancelEncounter(context.Context, *connect.Request[v1.CancelEncounterRequest]) (*connect.Response[v1.CancelEncounterResponse], error)
	ReopenEncounter(context.Context, *connect.Request[v1.ReopenEncounterRequest]) (*connect.Response[v1.ReopenEncounterResponse], error)
	SetEncounterLeave(context.Context, *connect.Request[v1.SetEncounterLeaveRequest]) (*connect.Response[v1.SetEncounterLeaveResponse], error)
	GetEncounter(context.Context, *connect.Request[v1.GetEncounterRequest]) (*connect.Response[v1.GetEncounterResponse], error)
	ListEncounters(context.Context, *connect.Request[v1.ListEncountersRequest]) (*connect.Response[v1.ListEncountersResponse], error)
	// SRS-ENC-004. Multiple encounters reference one episode without copying
	// data.
	OpenEpisode(context.Context, *connect.Request[v1.OpenEpisodeRequest]) (*connect.Response[v1.OpenEpisodeResponse], error)
	SetEpisodeStatus(context.Context, *connect.Request[v1.SetEpisodeStatusRequest]) (*connect.Response[v1.SetEpisodeStatusResponse], error)
	ListEpisodes(context.Context, *connect.Request[v1.ListEpisodesRequest]) (*connect.Response[v1.ListEpisodesResponse], error)
	// SRS-ENC-005. Effective-dated, so authorization can evaluate whether a
	// clinician was looking after this patient at the time.
	AssignCareTeamMember(context.Context, *connect.Request[v1.AssignCareTeamMemberRequest]) (*connect.Response[v1.AssignCareTeamMemberResponse], error)
	EndCareTeamAssignment(context.Context, *connect.Request[v1.EndCareTeamAssignmentRequest]) (*connect.Response[v1.EndCareTeamAssignmentResponse], error)
	GetCareTeam(context.Context, *connect.Request[v1.GetCareTeamRequest]) (*connect.Response[v1.GetCareTeamResponse], error)
	// SRS-ENC-007. Append-only: a change of mind supersedes rather than
	// overwrites, because the trail is the clinical reasoning.
	RecordDiagnosis(context.Context, *connect.Request[v1.RecordDiagnosisRequest]) (*connect.Response[v1.RecordDiagnosisResponse], error)
	RetractDiagnosis(context.Context, *connect.Request[v1.RetractDiagnosisRequest]) (*connect.Response[v1.RetractDiagnosisResponse], error)
	ListDiagnoses(context.Context, *connect.Request[v1.ListDiagnosesRequest]) (*connect.Response[v1.ListDiagnosesResponse], error)
	// SRS-ENC-008, SRS-ENC-009. Closure lists what is blocking it, can be forced
	// where policy allows with an audited reason, and issues a stored summary
	// that is amended rather than rewritten.
	CloseEncounter(context.Context, *connect.Request[v1.CloseEncounterRequest]) (*connect.Response[v1.CloseEncounterResponse], error)
	AmendSummary(context.Context, *connect.Request[v1.AmendSummaryRequest]) (*connect.Response[v1.AmendSummaryResponse], error)
	GetSummaries(context.Context, *connect.Request[v1.GetSummariesRequest]) (*connect.Response[v1.GetSummariesResponse], error)
	SetClosurePolicy(context.Context, *connect.Request[v1.SetClosurePolicyRequest]) (*connect.Response[v1.SetClosurePolicyResponse], error)
	GetClosurePolicy(context.Context, *connect.Request[v1.GetClosurePolicyRequest]) (*connect.Response[v1.GetClosurePolicyResponse], error)
	ListClosureOverrides(context.Context, *connect.Request[v1.ListClosureOverridesRequest]) (*connect.Response[v1.ListClosureOverridesResponse], error)
	// SRS-ENC-011. Restricted entries the reader may not see are masked or
	// omitted, and the restricted read is explicitly audited.
	GetTimeline(context.Context, *connect.Request[v1.GetTimelineRequest]) (*connect.Response[v1.GetTimelineResponse], error)
}

